create table if not exists public.rugprint_token_associations(id uuid primary key default gen_random_uuid(),subject_type text not null check(subject_type in ('x','pumpfun','fomo','wallet')),subject_value text not null,token_mint text not null,role text not null check(role in ('creator','deployer','promoter','caller','trader','linked_wallet','other')),evidence_strength text not null default 'unverified' check(evidence_strength in ('confirmed','strong','possible','unverified')),confidence integer not null default 0 check(confidence between 0 and 100),source_url text,tx_signature text,evidence jsonb not null default '[]'::jsonb,first_seen timestamptz not null default now(),last_seen timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(subject_type,subject_value,token_mint,role,source_url));alter table public.rugprint_token_associations enable row level security;create index if not exists rugprint_token_associations_subject_idx on public.rugprint_token_associations(subject_type,lower(subject_value));create index if not exists rugprint_token_associations_token_idx on public.rugprint_token_associations(token_mint);create index if not exists rugprint_token_associations_role_idx on public.rugprint_token_associations(role,evidence_strength,confidence desc);notify pgrst,'reload schema';